qs.append({"q":"Sir Syed Ahmed Khan opposed active political participation by Muslims in the immediate term mainly because:","o":["He believed Muslims should first focus on education and employment before engaging in politics to avoid inviting government hostility","He supported the Indian National Congress's political programme fully","He believed Islam forbade any political engagement with a non-Muslim government","He wanted Muslims to join the Wahabi Movement instead"],"a":0,"e":"Syed Ahmed Khan felt Muslims needed to catch up educationally and economically with Hindus before engaging in politics, fearing premature political activity would invite government hostility."})

